SELECT u.user_id, u.email, u.full_name, u.phone, u.bio, u.avatar_url, u.status, u.is_first_login, u.trust_score, u.banned_reason, u.created_at, u.updated_at FROM users u INNER JOIN user_roles ur ON ur.user_id = u.user_id INNER JOIN roles r ON r.role_id = ur.role_id
r.name = 'USER'
AND ( LOWER(u.email) LIKE LOWER(CONCAT('%', #{searchText}, '%')) OR LOWER(u.full_name) LIKE LOWER(CONCAT('%', #{searchText}, '%')) OR LOWER(u.phone) LIKE LOWER(CONCAT('%', #{searchText}, '%')) )
AND u.status = #{status}
ORDER BY u.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM users u
AND ( LOWER(u.email) LIKE LOWER(CONCAT('%', #{searchText}, '%')) OR LOWER(u.full_name) LIKE LOWER(CONCAT('%', #{searchText}, '%')) OR LOWER(u.phone) LIKE LOWER(CONCAT('%', #{searchText}, '%')) )
AND u.status = #{status}
